/* HEXA BATTLEGROUNDS setup — PART 85 OF 94. Run parts in order. Safe to re-run. */ create function _auto_preset(p_length text) returns jsonb language sql immutable as $$ select case p_length when '60' then _auto_preset_v14('full') || jsonb_build_object( 'phase_schedule', '3,11,20,29', 'finale_minute', 38, 'finale_battles', 3, 'zone_shrink', 50, 'zone_warning', 50, 'airdrop_interval', 4, 'red_interval', 5, 'lock_interval', 170, 'lock_warning', 45, 'recovery_seconds', 100, 'attack_cooldown', 75, 'protect_seconds', 100, 'boarding_seconds', 30, 'pickup_respawn', 75, 'game_minutes', 60) when '90' then _auto_preset_v14('full') || jsonb_build_object( 'phase_schedule', '3,17,32,47', 'finale_minute', 66, 'finale_battles', 3, 'zone_shrink', 70, 'zone_warning', 60, 'airdrop_interval', 5, 'red_interval', 6, 'lock_interval', 230, 'lock_warning', 50, 'recovery_seconds', 120, 'attack_cooldown', 90, 'protect_seconds', 120, 'boarding_seconds', 30, 'pickup_respawn', 90, 'game_minutes', 90) when '120' then _auto_preset_v14('full') || jsonb_build_object( 'phase_schedule', '4,23,44,65', 'finale_minute', 92, 'finale_battles', 4, 'zone_shrink', 90, 'zone_warning', 75, 'airdrop_interval', 6, 'red_interval', 7, 'lock_interval', 290, 'lock_warning', 55, 'recovery_seconds', 130, 'attack_cooldown', 100, 'protect_seconds', 130, 'boarding_seconds', 35, 'pickup_respawn', 100, 'game_minutes', 120) else _auto_preset_v14(p_length) end $$; drop function if exists _host_online_auto_v14(text, text, boolean); alter function host_online_auto(text, text, boolean) rename to _host_online_auto_v14; create function host_online_auto(p_token text, p_length text default 'standard', p_on boolean default true) returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_len text := coalesce(nullif(p_length, ''), 'standard'); v_hours boolean; begin v_ev := _auth_host(p_token); v_hours := v_len in ('60', '90', '120'); if coalesce(p_on, true) then update events set settings = settings || jsonb_build_object('auto_reveal', 0) where id = v_ev; end if; perform _host_online_auto_v14(p_token, case when v_hours then 'full' else v_len end, p_on); if v_hours and coalesce(p_on, true) then update events set settings = settings || _auto_preset(v_len) || jsonb_build_object('online_auto_length', v_len) where id = v_ev; end if; return host_online_summary(p_token); end $$; drop function if exists _host_online_start_v14(text, text); alter function host_online_start(text, text) rename to _host_online_start_v14; create function host_online_start(p_token text, p_length text default 'standard') returns jsonb language plpgsql security definer set search_path = public as $$ declare v_ev uuid; v_len text := coalesce(nullif(p_length, ''), 'standard'); r jsonb; begin v_ev := _auth_host(p_token); update events set settings = settings || jsonb_build_object('auto_reveal', 0) where id = v_ev; r := _host_online_start_v14(p_token, case when v_len in ('60', '90', '120') then 'full' else v_len end); if v_len in ('60', '90', '120') then update events set settings = settings || _auto_preset(v_len) where id = v_ev; end if; return r; end $$; do $$ declare src text; out text; begin src := pg_get_functiondef('_autopilot(uuid)'::regprocedure); if position('auto_reveal' in src) > 0 then return; end if; out := regexp_replace(src, 'elsif\s+v_pos\s*=\s*5\s*\+\s*v_n\s+then', 'elsif v_pos = 5 + v_n and _cfg(v_ev, ''auto_reveal'') = 1 then'); out := regexp_replace(out, 'elsif\s+v_pos\s*=\s*6\s*\+\s*v_n\s+then', 'elsif v_pos = 6 + v_n and _cfg(v_ev, ''auto_reveal'') = 1 then'); out := regexp_replace(out, 'if\s+v_pos\s*<\s*6\s*\+\s*v_n\s+or', 'if (v_pos < 5 + v_n or _cfg(v_ev, ''auto_reveal'') = 1) or'); if out = src or (length(out) - length(replace(out, 'auto_reveal', ''))) / length('auto_reveal') <> 3 then raise exception 'autopilot patch did not apply cleanly'; end if; execute out; end $$; create or replace function _auto_step_name(p_pos int, p_n int) returns text language sql immutable as $$ select case when p_pos <= 0 then 'Finale entry round' when p_pos = 1 then 'Exchange round' when p_pos <= 1 + p_n then 'Finale battle ' || p_pos when p_pos = 2 + p_n then 'Final lockdown' when p_pos = 3 + p_n then 'Final code' when p_pos = 4 + p_n then 'Results locked' when p_pos = 5 + p_n then 'Winner reveal by the host' when p_pos = 6 + p_n then 'Grand champion' else 'Match complete' end $$; do $$ declare f record; begin for f in select p.oid::regprocedure as sig, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' loop execute format('revoke all on function %s from public', f.sig); begin execute format('revoke all on function %s from anon, authenticated', f.sig); exception when undefined_object then null; end; if f.proname = any(array['map_data', 'join_team', 'claim_role', 'player_state', 'captain_move', 'captain_explore', 'captain_submit', 'captain_hint', 'captain_use_item', 'captain_buy', 'captain_attack', 'captain_claim_airdrop', 'captain_chat', 'captain_block', 'captain_report', 'captain_alliance', 'captain_bargain', 'host_create_event', 'host_login', 'host_generate_teams', 'host_import_teams', 'host_overview', 'host_command', 'host_settings', 'host_missions', 'host_save_mission', 'host_test_answer', 'host_chat_log', 'host_audit', 'host_export', 'spectator_state', 'host_roster', 'captain_steer', 'captain_reveal', 'captain_stairs', 'arena_positions', 'host_fixed_cards', 'card_event', 'demo_create', 'host_extras', 'demo_view', 'demo_status', 'demo_control', 'demo_pulse', 'demo_end', 'captain_vehicle', 'squad_fire', 'join_flight', 'captain_jump', 'captain_lift', 'online_join', 'squad_chat_send', 'squad_chat', 'host_attendance', 'host_online_summary', 'host_online_start', 'host_online_auto', 'host_online_launch', 'online_event_info', 'online_join_segue']) then begin execute format('grant execute on function %s to anon, authenticated', f.sig); exception when undefined_object then null; end; end if; end loop; end $$; alter table teams add column if not exists vest_lvl int not null default 0; alter table teams add column if not exists helmet_lvl int not null default 0; alter table teams add column if not exists weapon_sel text; alter table pickups drop constraint if exists pickups_kind_check; alter table pickups add constraint pickups_kind_check check (kind in ('medkit', 'shield', 'coins', 'ammo_light', 'ammo_rifle', 'ammo_shell', 'gun_smg', 'gun_shotgun', 'gun_ar', 'gun_sniper', 'vest1', 'vest2', 'vest3', 'helmet1', 'helmet2', 'helmet3', 'jammer')); insert into items(id, name, kind, description, params, price) values ('shotgun', 'Shotgun', 'weapon', 'Close range, two shells, huge damage.', '{"tag":"duel_smg","damage":35,"seconds":50,"consumable":false}'::jsonb, 45), ('ar', 'Assault Rifle', 'weapon', 'All-rounder: long range, 30-round magazine.', '{"tag":"duel_smg","damage":25,"seconds":60,"consumable":false}'::jsonb, 55), ('ammo_light', 'Light ammo', 'ammo', 'For the SMG.', '{}'::jsonb, 10), ('ammo_rifle', 'Rifle ammo', 'ammo', 'For the Assault Rifle and the Sniper.', '{}'::jsonb, 12), ('ammo_shell', 'Shotgun shells', 'ammo', 'For the Shotgun.', '{}'::jsonb, 10) on conflict (id) do update set name = excluded.name, kind = excluded.kind, description = excluded.description, params = excluded.params, price = excluded.price; update items set params = params || '{"consumable": false}'::jsonb where id in ('smg', 'sniper'); drop function if exists _defaults_v15(); alter function _defaults() rename to _defaults_v15; create function _defaults() returns jsonb language sql immutable as $$ select _defaults_v15() || jsonb_build_object( 'kill_points', 100, 'kill_coins', 40, 'pickup_medkit', 24, 'pickup_shield', 12, 'ammo_cap', 300, 'loot_ammo_light', 14, 'loot_ammo_rifle', 14, 'loot_ammo_shell', 8, 'loot_gun_smg', 5, 'loot_gun_shotgun', 4, 'loot_gun_ar', 5, 'loot_gun_sniper', 2, 'loot_vest1', 6, 'loot_vest2', 4, 'loot_vest3', 2, 'loot_helmet1', 6, 'loot_helmet2', 4, 'loot_helmet3', 2, 'loot_jammer', 3) $$; create or replace function _online_map_size(p_ev uuid) returns int language sql stable as $$ select least(40, greatest(1, _cfg(p_ev, 'arena_size'))) $$; do $$ declare f record; src text; out text; begin for f in select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prokind = 'f' and pg_get_functiondef(p.oid) like '%least(15, greatest(1, _cfg(v_ev, ''arena_size'')))%' loop src := pg_get_functiondef(f.sig); out := replace(src, 'least(15, greatest(1, _cfg(v_ev, ''arena_size'')))', 'least(40, greatest(1, _cfg(v_ev, ''arena_size'')))'); execute out; end loop; end $$; create or replace function _gun(p_id text) returns jsonb language sql immutable as $$ select case p_id when 'smg' then '{"id":"smg","name":"SMG","dmg":2,"range":0.04,"rate":260,"mag":30,"reload":2000,"ammo":"ammo_light"}'::jsonb when 'shotgun' then '{"id":"shotgun","name":"Shotgun","dmg":9,"range":0.028,"rate":950,"mag":2,"reload":2300,"ammo":"ammo_shell"}'::jsonb when 'ar' then '{"id":"ar","name":"Assault Rifle","dmg":4,"range":0.075,"rate":420,"mag":30,"reload":2300,"ammo":"ammo_rifle"}'::jsonb when 'sniper' then '{"id":"sniper","name":"Sniper","dmg":16,"range":0.11,"rate":1700,"mag":5,"reload":2600,"ammo":"ammo_rifle"}'::jsonb else '{"id":"pistol","name":"Pistol","dmg":3,"range":0.055,"rate":650,"mag":12,"reload":1600,"ammo":null}'::jsonb end $$; create or replace function _has_gun(p_team uuid, p_gun text) returns boolean language sql stable as $$ select p_gun = 'pistol' or ( exists (select 1 from inventory where team_id = p_team and item_id = p_gun and qty > 0) and coalesce((select qty from inventory where team_id = p_team and item_id = _gun(p_gun) ->> 'ammo'), 0) > 0) $$; create or replace function _weapon(p_team uuid) returns jsonb language sql stable as $$ select coalesce( (select _gun(t.weapon_sel) from teams t where t.id = p_team and t.weapon_sel is not null and _has_gun(p_team, t.weapon_sel)), (select _gun(g) from unnest(array['ar', 'smg', 'shotgun', 'sniper']) with ordinality u(g, o) where _has_gun(p_team, g) order by o limit 1), _gun('pistol')) $$; create or replace function squad_equip(p_token text, p_gun text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; begin p := _auth_player(p_token); if p.role is null then raise exception 'NO_ROLE'; end if; if coalesce(p_gun, '') not in ('pistol', 'smg', 'shotgun', 'ar', 'sniper') then raise exception 'BAD_ITEM'; end if; select * into t from teams where id = p.team_id; if p_gun <> 'pistol' and not exists (select 1 from inventory where team_id = t.id and item_id = p_gun and qty > 0) then raise exception 'NO_ITEM'; end if; if not _has_gun(t.id, p_gun) then raise exception 'NO_AMMO'; end if; update teams set weapon_sel = p_gun where id = t.id; update players set mag = null, reload_until = null where team_id = t.id; perform _ping_team(t.id, 'item'); return jsonb_build_object('weapon', _weapon(t.id)); end $$; drop function if exists _squad_fire_v15(text, uuid); alter function squad_fire(text, uuid) rename to _squad_fire_v15; create function squad_fire(p_token text, p_target uuid) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; r jsonb; w jsonb; v_left int; d teams; xy float8[]; k text; begin p := _auth_player(p_token); w := _weapon(p.team_id); r := _squad_fire_v15(p_token, p_target); if w ->> 'ammo' is not null then perform _add_item(p.team_id, w ->> 'ammo', -1); select qty into v_left from inventory where team_id = p.team_id and item_id = w ->> 'ammo'; r := r || jsonb_build_object('ammo_left', coalesce(v_left, 0)); if coalesce(v_left, 0) <= 0 then r := r || jsonb_build_object('out_of_ammo', true, 'weapon', _weapon(p.team_id)); end if; end if; if coalesce((r ->> 'knocked')::boolean, false) then select * into d from teams where id = p_target; xy := _team_xy(d); foreach k in array array['ammo_rifle', 'ammo_light', 'medkit'] || case when d.vest_lvl > 0 then array['vest' || d.vest_lvl] else array[]::text[] end loop insert into pickups(arena_id, kind, x, y, level, bldg) values (d.arena_id, k, greatest(0.02, least(0.98, xy[1] + (random() - 0.5) * 0.006)), greatest(0.02, least(0.98, xy[2] + (random() - 0.5) * 0.006)), d.level, d.bldg); end loop; perform _ping_arena(d.arena_id, 'pickup'); r := r || jsonb_build_object('elimination', jsonb_build_object('points', _cfg(d.event_id, 'kill_points'), 'coins', _cfg(d.event_id, 'kill_coins'))); end if; return r; end $$; create or replace function _gun_starter_ammo() returns trigger language plpgsql as $$ declare v_ammo text; v_have int; begin if new.item_id in ('smg', 'shotgun', 'ar', 'sniper') and new.qty > 0 and (tg_op = 'INSERT' or coalesce(old.qty, 0) = 0) then v_ammo := _gun(new.item_id) ->> 'ammo'; select qty into v_have from inventory where team_id = new.team_id and item_id = v_ammo; if coalesce(v_have, 0) = 0 then insert into inventory(team_id, item_id, qty) values (new.team_id, v_ammo, case new.item_id when 'shotgun' then 10 when 'sniper' then 10 else 30 end) on conflict (team_id, item_id) do update set qty = excluded.qty; end if; end if; return new; end $$; drop trigger if exists inventory_gun_ammo on inventory; create trigger inventory_gun_ammo after insert or update of qty on inventory for each row execute function _gun_starter_ammo(); drop function if exists _damage_v15(uuid, int, text, text, text); alter function _damage(uuid, int, text, text, text) rename to _damage_v15; create function _damage(p_team uuid, p_amount int, p_kind text, p_ref text, p_reason text) returns int language plpgsql as $$ declare v_v int; v_h int; v_amt int := p_amount; begin if p_kind = 'gunfire' and p_amount > 0 then select vest_lvl, helmet_lvl into v_v, v_h from teams where id = p_team; v_amt := greatest(1, round(p_amount * (1 - (least(3, coalesce(v_v, 0)) * 10 + least(3, coalesce(v_h, 0)) * 5) / 100.0))::int); end if; return _damage_v15(p_team, v_amt, p_kind, p_ref, p_reason); end $$; do $$ declare src text; out text; begin src := pg_get_functiondef('_take_pickups(uuid, double precision, double precision)'::regprocedure); if position('''medkit'', ''shield'', ''coins''' in src) > 0 then return; end if; out := regexp_replace(src, 'taken_at\s+is\s+null\s+and\s+level\s*=\s*t\.level', 'taken_at is null and kind in (''medkit'', ''shield'', ''coins'') and level = t.level'); if out = src then raise exception 'pickup patch did not apply'; end if; execute out; end $$; drop function if exists _take_pickups_v15(uuid, double precision, double precision); alter function _take_pickups(uuid, double precision, double precision) rename to _take_pickups_v15; create function _take_pickups(p_team uuid, p_x double precision, p_y double precision) returns jsonb language plpgsql as $$ declare t teams; pk pickups; v_out jsonb := '[]'::jsonb; v_old jsonb; g text; v_lvl int; v_have int; v_cap int; v_ammo text; v_n int; begin select * into t from teams where id = p_team; v_cap := _cfg(t.event_id, 'ammo_cap'); for pk in select * from pickups where arena_id = t.arena_id and taken_at is null and level = t.level and kind not in ('medkit', 'shield', 'coins') and (x - p_x) ^ 2 + (y - p_y) ^ 2 <= 0.013 ^ 2 for update skip locked loop if pk.kind like 'gun\_%' then g := substring(pk.kind from 5); v_ammo := _gun(g) ->> 'ammo'; v_n := case g when 'shotgun' then 10 when 'sniper' then 10 else 60 end; if not exists (select 1 from inventory where team_id = t.id and item_id = g and qty > 0) then perform _add_item(t.id, g, 1); if t.weapon_sel is null or t.weapon_sel = 'pistol' then update teams set weapon_sel = g where id = t.id; end if; else select coalesce(qty, 0) into v_have from inventory where team_id = t.id and item_id = v_ammo; if coalesce(v_have, 0) >= v_cap then continue; end if; end if; select coalesce(qty, 0) into v_have from inventory where team_id = t.id and item_id = v_ammo; perform _add_item(t.id, v_ammo, least(v_n, v_cap - coalesce(v_have, 0))); elsif pk.kind like 'ammo\_%' then select coalesce(qty, 0) into v_have from inventory where team_id = t.id and item_id = pk.kind; if coalesce(v_have, 0) >= v_cap then continue; end if; perform _add_item(t.id, pk.kind, least(case pk.kind when 'ammo_shell' then 10 else 40 end, v_cap - coalesce(v_have, 0))); elsif pk.kind like 'vest_' then v_lvl := right(pk.kind, 1)::int; if v_lvl <= t.vest_lvl then continue; end if; update teams set vest_lvl = v_lvl where id = t.id; elsif pk.kind like 'helmet_' then v_lvl := right(pk.kind, 1)::int; if v_lvl <= t.helmet_lvl then continue; end if; update teams set helmet_lvl = v_lvl where id = t.id; elsif pk.kind = 'jammer' then select coalesce(qty, 0) into v_have from inventory where team_id = t.id and item_id = 'jammer'; if coalesce(v_have, 0) >= 2 then continue; end if; perform _add_item(t.id, 'jammer', 1); else continue; end if; update pickups set taken_by = t.id, taken_at = now() where id = pk.id; v_out := v_out || jsonb_build_array(pk.kind); end loop; v_old := _take_pickups_v15(p_team, p_x, p_y); if v_old is not null then v_out := v_out || v_old; end if; if jsonb_array_length(v_out) = 0 then return null; end if; if v_old is null then perform _ping_arena(t.arena_id, 'pickup'); end if; return v_out; end $$; drop function if exists _spawn_pickups_v15(uuid); alter function _spawn_pickups(uuid) rename to _spawn_pickups_v15;
